package jwt.service;import jwt.entity.User;import jwt.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.security.core.userdetails.UserDetailsService;import org.springframework.security.core.userdetails.UsernameNotFoundException;import org.springframework.stereotype.Service;@Service@RequiredArgsConstructorpublic class CustomUserDetailsServiceimplements UserDetailsService {    private final UserRepository repository;    @Override    public UserDetails loadUserByUsername(String username)            throws UsernameNotFoundException {        User user=repository.findByUsername(username)                .orElseThrow(()->new UsernameNotFoundException("User not found"));        return org.springframework.security.core.userdetails.User                .withUsername(user.getEmail())                .password(user.getPassword())                .roles(user.getRole())                .build();    }}